\documentclass{beamer}
\usetheme{default}
\begin{document}
\begin{frame}{Overview}
\begin{itemize}
\item Tokamak operation needs real-time magnetic control.
\item Disruptions must be detected milliseconds ahead.
\end{itemize}
\end{frame}
\begin{frame}{Plasma Models}
The pressure ratio follows $\beta = 2\mu_0 p / B^2$ in equilibrium.
Confinement of \alpha particles sets the heating budget.
\end{frame}
\begin{frame}{Control Loop}
\begin{enumerate}
\item Measure the safety factor $q$ at the plasma edge.
\item Adjust the coil current within one control cycle.
\end{frame}
\begin{frame}{Summary}
Stable operation is achievable with fast feedback and disruption predictors.
\end{document}

